%[text] %[text:anchor:T_1FFD3858] # Longitudinal Vehicle - Simulation Case
%[text] %[text:anchor:H_1B376934] ## Coast-down
model_name = "HarnessModel_Vehicle1D";
load_system(model_name)

Vehicle1D_Basic_params

loadLUTData_Vehicle1D_Zero

initial.vehicle_speed_kph = 100;

sim_in = Simulink.SimulationInput(model_name);
sim_in = setBlockParameter(sim_in, model_name + "/Inputs", ReferencedSubsystem = "Inputs_Vehicle1D_LookupTables_refsub");
sim_in = setBlockParameter(sim_in, model_name + "/Longitudinal Vehicle", ReferencedSubsystem = "Vehicle1D_Basic_refsub");
sim_in = setModelParameter(sim_in, StopTime = "200");
applyToModel(sim_in)
sim_out = sim(sim_in);

result = extractTimetable(sim_out.logsout);

signal_names = [
  "Axle torque input"
  "Brake force"
  "Road inclination"
  "Road grade"
  "G force"
  "Vehicle speed kph"
  "Vehicle speed mph"
  "Axle speed"
  ];

for k = 1 : numel(signal_names) %[output:group:4bb30e90]
  fig = bevutil1.SignalUtil.plotTimedData(TimedData = result, SignalName = signal_names(k)); %[output:12a91717] %[output:3b50217b] %[output:5630f600] %[output:1c2a1e51] %[output:97f619da] %[output:597b9e5c] %[output:3741834d] %[output:1b26320b]
  fig.Position(4) = 200;  % height
end  % for %[output:group:4bb30e90]
